/**
 * Skill package lookup, ported from GameServerJS players/inc_skill_packages.js
 * (getSkillPackageDetails) and players/inc_skills.js (skills_get_highest_level).
 *
 * A package (catalog_skill_packages.js) holds one row per qualifying skill.
 * The player uses the highest-ranked row they qualify for: `no_skill` always
 * qualifies, every other row needs that exact skill learned. Imagination
 * upgrades then overlay drop/bonus fields and scale duration per category.
 *
 * Data: ./skill-packages-data.js (generated by build-skill-packages.mjs).
 */

import { SKILL_PACKAGES } from './skill-packages-data.js?v=cb4e9ab3';

export { SKILL_PACKAGES };

function asSet(list) {
  if (list instanceof Set) return list;
  return new Set(Array.isArray(list) ? list : []);
}

/**
 * players/inc_skill_packages.js addSkillPackageOverride /
 * removeSkillPackageOverride: per-player field overrides that
 * getSkillPackageDetails writes over the chosen row last (lines 671-675).
 * Buffs set them (Impervious Miner, Easy Animalia, Bubble-Enhanced
 * Meditation, Flaming Grinder, Smelt It, Dealt It); the remake has one
 * player, so the table is module-wide and the buff feature rebuilds it
 * from the running buffs after a reload.
 */
const PACKAGE_OVERRIDES = {};

export function addSkillPackageOverride(packageId, fields = {}) {
  if (!packageId || !fields || typeof fields !== 'object') return;
  PACKAGE_OVERRIDES[packageId] = { ...(PACKAGE_OVERRIDES[packageId] || {}), ...fields };
}

export function removeSkillPackageOverride(packageId) {
  delete PACKAGE_OVERRIDES[packageId];
}

/** The override fields for a package (a copy), or null. */
export function getSkillPackageOverride(packageId) {
  const o = PACKAGE_OVERRIDES[packageId];
  return o ? { ...o } : null;
}

export function clearSkillPackageOverrides() {
  for (const id of Object.keys(PACKAGE_OVERRIDES)) delete PACKAGE_OVERRIDES[id];
}

/**
 * Exact port of getSkillPackageDetails. Returns a fresh copy (callers may
 * adjust it) with `skill` naming the row that applied, or null when the
 * player qualifies for no row (for example Mining without Mining I).
 * @param {string} packageId
 * @param {string[]|Set<string>} [learned]
 * @param {string[]|Set<string>} [upgrades]
 */
export function skillPackageDetails(packageId, learned = [], upgrades = []) {
  const pkg = SKILL_PACKAGES[packageId];
  if (!pkg?.skills) return null;
  const known = asSet(learned);
  let details = null;
  let skill = null;
  for (const [id, row] of Object.entries(pkg.skills)) {
    if ((!details || row.rank > details.rank) && (id === 'no_skill' || known.has(id))) {
      details = row;
      skill = id;
    }
  }
  if (!details) return null;
  const out = { ...details, skill };
  const owned = asSet(upgrades);
  const imgRank = {};
  let durationMultiplier = 0;
  for (const [upgradeId, img] of Object.entries(pkg.img_upgrades || {})) {
    const [a, b] = String(img.rank).split('.');
    const cat = b !== undefined ? Number(a) || 0 : 0;
    const rank = b !== undefined ? Number(b) || 0 : Number(a) || 0;
    if ((!imgRank[cat] || imgRank[cat] < rank) && owned.has(upgradeId)) {
      imgRank[cat] = rank;
      for (const key of ['drop_class_id', 'drop_chance', 'bonus_multiplier', 'bonus_chance', 'bonus_amount']) {
        if (img[key] !== undefined) out[key] = img[key];
      }
      if (img.duration_multiplier !== undefined && img.duration_multiplier !== 0) {
        durationMultiplier = img.duration_multiplier;
      }
    }
  }
  // duration and duration_max both scale (inc_skill_packages.js:659-669).
  for (const key of ['duration', 'duration_max']) {
    if (durationMultiplier && Number.isFinite(out[key])) {
      out[key] += durationMultiplier > 0
        ? -(out[key] * durationMultiplier)
        : out[key] * Math.abs(durationMultiplier);
    }
  }
  // Overrides last (inc_skill_packages.js:671-675).
  const override = PACKAGE_OVERRIDES[packageId];
  if (override) Object.assign(out, override);
  return out;
}

/** Rank of the applied row: -1 for no_skill, null when nothing qualifies. */
export function skillPackageRank(packageId, learned = []) {
  const details = skillPackageDetails(packageId, learned);
  return details ? details.rank : null;
}

/**
 * skills_get_highest_level: the highest consecutive level of a skill family,
 * from any member id (`ezcooking_1` → 2 when EZ Cooking I and II are known).
 * @param {string[]|Set<string>} learned
 * @param {string} skillId
 */
export function highestSkillLevel(learned, skillId) {
  const id = String(skillId || '');
  const sep = id.lastIndexOf('_');
  if (sep === -1) return 0;
  const base = id.slice(0, sep);
  const known = asSet(learned);
  let level = 0;
  for (let i = 1; known.has(`${base}_${i}`); i += 1) level = i;
  return level;
}

/** Source `is_chance(fraction)`; Max Luck callers pass `rng = () => 0`. */
export function isChance(fraction, rng = Math.random) {
  return rng() < Number(fraction || 0);
}

/** Source `drop_chance` is a whole-number percentage. */
export function dropChanceHit(details, rng = Math.random) {
  return Boolean(details?.drop_class_id) && rng() * 100 < Number(details.drop_chance || 0);
}
